  operation: string;
  reservedOutputTokens: number;
  safeRatio: number;
  fixedOverheadTokens: number;
  chargeUser: boolean;
}

async function checkBudget(policy: BudgetPolicy, fragments: Fragment[]): Promise<BudgetResult> {
  const estimated = await estimateTokens(fragments);
  if (estimated > policy.reservedOutputTokens * policy.safeRatio) {
    return { status: 'compress', estimated };
  }
  return { status: 'ok', estimated };
}
